[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Command packet missing: $rel"};$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)));if($raw -match '(?i)"(?:secondBus|sharedSerializedState)"\s*:\s*(?:true|"true")'){throw 'Command packet declares a forbidden parallel bus or shared per-run state.'};$p=$raw|ConvertFrom-Json;foreach($x in @('schemaVersion','commandId','category','serializedContext','runner','startPolicy','stopPolicy','ownership','cancellation','reentrancy','evidenceRef','staleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Command field missing: $x"}};if([string]$p.schemaVersion -ne '1'-or [string]$p.runner -ne 'ESCommandPlayerRunner'){throw 'Command packet must use schemaVersion 1 and the authoritative runner.'};if([string]$p.reentrancy -notmatch '^(per-run|serialized-instance)$'){throw 'Invalid reentrancy policy.'};Write-Output "PASS: ESCommand packet preserves category, context, authoritative Runner and lifecycle boundaries: $rel"
